INSERT T3.[CFDI_AGRUPACION_PAGO]([AGRUPACION],[FECHA_PAGO],[ASIGNACION_ID]) SELECT [AGRUPACION],[FECHA_PAGO],[ASIGNACION_ID] FROM [REPAIR_AGR_20261028].[Origen_CFDI_AGRUPACION_PAGO];
IF EXISTS(SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM T3.[CFDI_AGRUPACION_PAGO] T WHERE AGRUPACION IN (514957,514969,514981,514984,529050,529096,529120,529179) OR ASIGNACION_ID IN ('262201997234','262201997964','262201997720','262201997198')) L GROUP BY H EXCEPT SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM [REPAIR_AGR_20261028].[Origen_CFDI_AGRUPACION_PAGO] T WHERE 1=1) R GROUP BY H) OR EXISTS(SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM [REPAIR_AGR_20261028].[Origen_CFDI_AGRUPACION_PAGO] T WHERE 1=1) R GROUP BY H EXCEPT SELECT H,COUNT_BIG(*) N FROM (SELECT HASHBYTES('SHA2_256',(SELECT T.* FOR JSON PATH,INCLUDE_NULL_VALUES,WITHOUT_ARRAY_WRAPPER)) H FROM T3.[CFDI_AGRUPACION_PAGO] T WHERE AGRUPACION IN (514957,514969,514981,514984,529050,529096,529120,529179) OR ASIGNACION_ID IN ('262201997234','262201997964','262201997720','262201997198')) L GROUP BY H) THROW 52909,'La comprobacion posterior fallo: CFDI_AGRUPACION_PAGO.',1;
DECLARE @Max decimal(38,0),@Actual decimal(38,0),@Limite decimal(38,0),@Incremento decimal(38,0),@Proximo decimal(38,0),@SQL nvarchar(300);
SELECT @Actual=CONVERT(decimal(38,0),current_value),@Limite=CONVERT(decimal(38,0),maximum_value),@Incremento=CONVERT(decimal(38,0),increment) FROM sys.sequences WHERE object_id=OBJECT_ID('T3.SEQ_PAGO_CENTRAL_AGR');
IF @Limite IS NULL OR @Incremento<>1 THROW 52910,'Secuencia ausente o incremento no soportado.',1;
SELECT @Max=MAX(N) FROM (SELECT MAX(AGRUPACION) N FROM T3.CFDI_AGRUPACION_CTRL UNION ALL SELECT MAX(AGRUPACION) FROM T3.CFDI_AGRUPACION_PAGO UNION ALL SELECT MaxOrigen FROM [REPAIR_AGR_20261028].Estado UNION ALL SELECT @Actual) X;
IF @Max>=@Limite THROW 52911,'Rango agotado de secuencia.',1; SET @Proximo=@Max+1;
SELECT @Aplicar Aplicar,@Proximo ProximoValorPropuesto;
IF @Aplicar=1 BEGIN
SET @SQL=N'ALTER SEQUENCE T3.SEQ_PAGO_CENTRAL_AGR RESTART WITH '+CONVERT(nvarchar(40),@Proximo); EXEC sys.sp_executesql @SQL;
UPDATE [REPAIR_AGR_20261028].Estado SET Fase='APLICADO',Aplicacion=SYSDATETIME() WHERE Id=1;
COMMIT; SELECT 'APLICADO' Resultado; END ELSE BEGIN ROLLBACK; SELECT 'ENSAYO CORRECTO; TODOS LOS CAMBIOS REVERTIDOS' Resultado; END;
END TRY
